// apiKeyJSON is how an API key is shown. Neither the token's hash nor the token itself is shown, except in the answer
// that creates the key, which carries the token once.
type apiKeyJSON struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Last4      string     `json:"last4"`
	CreatedAt  time.Time  `json:"created_at"`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
	Token      string     `json:"token,omitempty"`
}

// apiKeyView shows a key. k.Token is set only on the value that created the key.
func apiKeyView(k store.APIKey) apiKeyJSON {
	return apiKeyJSON{ID: k.ID, OrgID: k.OrgID, UserID: k.UserID, Name: k.Name, Last4: k.Last4, CreatedAt: k.CreatedAt,
		LastUsedAt: k.LastUsedAt, RevokedAt: k.RevokedAt, Token: k.Token}
}

func (s *Server) listAPIKeys(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []apiKeyJSON{}
	for _, k := range s.store.APIKeys(p.OrgID) {
		items = append(items, apiKeyView(k))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

